"use strict";

const https = require("https");
const http = require("http");
const zlib = require("zlib");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
  "(KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const FETCH_HEADERS = {
  "user-agent": UA,
  accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  referer: "https://www.tiktok.com/",
};

async function fetchHtmlWithFetch(url) {
  const res = await fetch(url, {
    headers: FETCH_HEADERS,
    redirect: "follow",
  });
  if (!res.ok) throw new Error(`TikTok page fetch failed: HTTP ${res.status}`);
  const cookies =
    typeof res.headers.getSetCookie === "function"
      ? res.headers.getSetCookie().map((c) => c.split(";")[0])
      : [];
  return { html: await res.text(), finalUrl: res.url, cookies };
}

function fetchHtmlWithHttps(url, redirectCount) {
  const redirectsLeft = redirectCount == null ? 10 : redirectCount;
  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(url);
    } catch (e) {
      reject(new Error(`Invalid TikTok URL: ${url}`));
      return;
    }
    const lib = parsed.protocol === "http:" ? http : https;
    const req = lib.get(
      parsed,
      {
        headers: {
          ...FETCH_HEADERS,
          "accept-encoding": "gzip, deflate, br",
        },
        timeout: 20000,
      },
      (res) => {
        const status = res.statusCode || 0;
        const setCookie = res.headers["set-cookie"] || [];
        const cookies = Array.isArray(setCookie)
          ? setCookie.map((c) => String(c).split(";")[0])
          : [];

        if (
          status >= 300 &&
          status < 400 &&
          res.headers.location &&
          redirectsLeft > 0
        ) {
          res.resume();
          const nextUrl = new URL(res.headers.location, parsed).toString();
          fetchHtmlWithHttps(nextUrl, redirectsLeft - 1)
            .then((out) => {
              resolve({
                html: out.html,
                finalUrl: out.finalUrl,
                cookies: [...cookies, ...out.cookies],
              });
            })
            .catch(reject);
          return;
        }

        if (status < 200 || status >= 300) {
          res.resume();
          reject(new Error(`TikTok page fetch failed: HTTP ${status}`));
          return;
        }

        let stream = res;
        const encoding = String(res.headers["content-encoding"] || "").toLowerCase();
        if (encoding === "gzip" || encoding === "x-gzip") {
          stream = res.pipe(zlib.createGunzip());
        } else if (encoding === "deflate") {
          stream = res.pipe(zlib.createInflate());
        } else if (encoding === "br") {
          stream = res.pipe(zlib.createBrotliDecompress());
        }

        const chunks = [];
        stream.on("data", (chunk) => chunks.push(chunk));
        stream.on("end", () => {
          resolve({
            html: Buffer.concat(chunks).toString("utf8"),
            finalUrl: parsed.toString(),
            cookies,
          });
        });
        stream.on("error", reject);
        res.on("error", reject);
      }
    );
    req.on("timeout", () => {
      req.destroy(new Error("TikTok page fetch timed out"));
    });
    req.on("error", reject);
  });
}

async function fetchHtml(url) {
  if (typeof fetch === "function") {
    try {
      return await fetchHtmlWithFetch(url);
    } catch (e) {
      try {
        return await fetchHtmlWithHttps(url);
      } catch (_) {
        throw e;
      }
    }
  }
  return fetchHtmlWithHttps(url);
}

function extractScope(html) {
  const m = html.match(
    /<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" type="application\/json">([\s\S]*?)<\/script>/
  );
  if (!m) {
    throw new Error(
      "Rehydration JSON not found - TikTok page structure may have changed"
    );
  }
  const json = JSON.parse(m[1]);
  return json["__DEFAULT_SCOPE__"] || {};
}

function shapeAuthor(a) {
  if (!a) return null;
  return {
    id: a.id,
    uniqueId: a.uniqueId,
    nickname: a.nickname,
    avatar: a.avatarLarger || a.avatarMedium || a.avatarThumb || null,
    signature: a.signature || "",
    verified: !!a.verified,
    secUid: a.secUid || null,
  };
}

function shapeMusic(m) {
  if (!m) return null;
  return {
    id: m.id,
    title: m.title || "",
    authorName: m.authorName || "",
    playUrl: m.playUrl || null,
    cover: m.coverLarge || m.coverMedium || m.coverThumb || null,
    duration: m.duration || null,
    original: !!m.original,
  };
}

function shapeVideo(v) {
  if (!v) return null;
  const qualities = Array.isArray(v.bitrateInfo)
    ? v.bitrateInfo.map((b) => ({
        quality: b.QualityType,
        bitrate: b.Bitrate,
        codec: b.CodecType,
        width: b.PlayAddr && b.PlayAddr.Width,
        height: b.PlayAddr && b.PlayAddr.Height,
        size: b.PlayAddr && b.PlayAddr.DataSize,
        url: b.PlayAddr && b.PlayAddr.UrlList && b.PlayAddr.UrlList[0],
      }))
    : [];
  return {
    duration: v.duration,
    width: v.width,
    height: v.height,
    ratio: v.ratio,
    cover: v.cover || null,
    dynamicCover: v.dynamicCover || null,
    playAddr: v.playAddr || null,
    downloadAddr: v.downloadAddr || null,
    qualities,
  };
}

function shapeStats(s) {
  if (!s) return null;
  const n = (x) => (x == null ? null : Number(x));
  return {
    plays: n(s.playCount),
    likes: n(s.diggCount),
    comments: n(s.commentCount),
    shares: n(s.shareCount),
    collects: n(s.collectCount),
  };
}

function shapeImages(item) {
  const list =
    item && item.imagePost && Array.isArray(item.imagePost.images)
      ? item.imagePost.images
      : [];
  const out = [];
  for (const img of list) {
    const urls =
      img && img.imageURL && Array.isArray(img.imageURL.urlList)
        ? img.imageURL.urlList
        : [];
    if (urls[0]) out.push(urls[0]);
  }
  return out;
}

function shapeItem(item) {
  return {
    id: item.id,
    desc: item.desc || "",
    createTime: item.createTime ? Number(item.createTime) : null,
    author: shapeAuthor(item.author),
    music: shapeMusic(item.music),
    video: shapeVideo(item.video),
    images: shapeImages(item),
    stats: shapeStats(item.statsV2 || item.stats),
    isAd: !!item.isAd,
  };
}

async function getVideoSession(input) {
  if (!/tiktok\.com/.test(input)) {
    throw new Error("Expected a TikTok video URL (full or short link)");
  }
  const { html, finalUrl, cookies } = await fetchHtml(input);
  const scope = extractScope(html);
  const detail = scope["webapp.video-detail"];
  if (!detail || !detail.itemInfo || !detail.itemInfo.itemStruct) {
    const msg =
      (detail && detail.statusMsg) || "Video unavailable or removed";
    throw new Error(`Video data not found: ${msg}`);
  }
  const out = shapeItem(detail.itemInfo.itemStruct);
  out.url = finalUrl.split("?")[0];
  return { video: out, cookies };
}

async function fetchSelf(url) {
  if (!url || typeof url !== "string") {
    throw new Error("Self-scrape: a TikTok URL string is required");
  }

  let scraped;
  try {
    const { video } = await getVideoSession(url);
    scraped = video;
  } catch (e) {
    throw new Error(`Self-scrape failed: ${e && e.message ? e.message : e}`);
  }

  if (!scraped || !scraped.id) {
    throw new Error("Self-scrape failed: no video data in TikTok page");
  }

  const video = scraped.video || null;
  const images = Array.isArray(scraped.images) ? scraped.images : [];
  const isPhoto = images.length > 0;

  let noWatermark = null;
  if (video) {
    noWatermark = video.playAddr || video.downloadAddr || null;
    if (!noWatermark && Array.isArray(video.qualities)) {
      for (const q of video.qualities) {
        if (q && q.url) {
          noWatermark = q.url;
          break;
        }
      }
    }
  }
  if (isPhoto && noWatermark && /mime_type=audio/.test(noWatermark)) {
    noWatermark = null;
  }
  if (!noWatermark && !isPhoto) {
    throw new Error(
      "Self-scrape failed: could not extract a download URL from TikTok page"
    );
  }

  const author = scraped.author || null;
  const stats = scraped.stats || null;
  const music = scraped.music || null;

  return {
    success: true,
    source: "TikTok",
    data: {
      title: scraped.desc || "TikTok Video",
      type: isPhoto ? "photo" : "video",
      ...(isPhoto ? { images } : {}),
      thumbnail: (video && video.cover) || images[0] || null,
      owner: {
        username: author ? author.uniqueId || null : null,
        nickname: author ? author.nickname || null : null,
        avatar: author ? author.avatar || null : null,
      },
      stats: {
        likes: stats ? (stats.likes == null ? null : stats.likes) : null,
        comments: stats ? (stats.comments == null ? null : stats.comments) : null,
        plays: stats ? (stats.plays == null ? null : stats.plays) : null,
        shares: stats ? (stats.shares == null ? null : stats.shares) : null,
      },
      download: {
        no_watermark: noWatermark,
        watermark: null,
        music: music ? music.playUrl || null : null,
      },
    },
  };
}

module.exports = fetchSelf;
